def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def runs_on_edge(cells):
        runs = []
        i = 0
        while i < len(cells):
            if cells[i] == bg:
                i += 1
                continue
            color = cells[i]
            j = i + 1
            while j < len(cells) and cells[j] == color:
                j += 1
            if j - i >= 2:
                runs.append((color, i, j - i))
            i = j
        return runs

    def edge_pairs(edge1, edge2):
        pairs = []
        for color, start1, length1 in edge1:
            for color2, start2, length2 in edge2:
                if color == color2 and length1 == length2:
                    pairs.append((color, start1, start2, length1))
        return pairs

    markers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                markers.append((r, c, grid[r][c]))

    # Process paired bars along the top and bottom edges.
    for bar_color, top, bottom, length in edge_pairs(
        runs_on_edge(grid[0]), runs_on_edge(grid[-1])
    ):
        points = [(r, c, color) for r, c, color in markers if color != bar_color]
        for r, c, color in points:
            if top <= c < top + length:
                offset = c - top
                coords = ((c, 0), (bottom + offset, 1))
            elif bottom <= c < bottom + length:
                offset = c - bottom
                coords = ((c, 0), (top + offset, 1))
            else:
                continue

            for col, side in coords:
                step = 1 if side == 0 else -1
                rr = 1 if side == 0 else h - 2
                while 0 <= rr < h:
                    if any(mr == rr and mc == col for mr, mc, _ in markers):
                        out[rr][col] = 4
                        break
                    out[rr][col] = color
                    rr += step

    # Process paired bars along the left and right edges.
    for bar_color, left, right, length in edge_pairs(
        runs_on_edge([grid[r][0] for r in range(h)]),
        runs_on_edge([grid[r][-1] for r in range(h)])
    ):
        points = [(r, c, color) for r, c, color in markers if color != bar_color]
        for r, c, color in points:
            if left <= r < left + length:
                offset = r - left
                coords = ((r, 0), (right + offset, 1))
            elif right <= r < right + length:
                offset = r - right
                coords = ((r, 0), (left + offset, 1))
            else:
                continue

            for row, side in coords:
                step = 1 if side == 0 else -1
                cc = 1 if side == 0 else w - 2
                while 0 <= cc < w:
                    if any(mr == row and mc == cc for mr, mc, _ in markers):
                        out[row][cc] = 4
                        break
                    out[row][cc] = color
                    cc += step

    return out
